                {
                    "name": "Plain sencha or bancha (unblended)",
                    "ratio": "Use half the amount called for genmaicha",
                    "note": "Genmaicha is diluted with rice, so straight green tea leaves are more concentrated. Cutting the amount in half and steeping briefly avoids excess bitterness.",
                    "ratio_multiplier": 0.5,
                },
                {
                    "name": "Roasted rice tea without tea leaves (genmai yu)",
                    "ratio": "1:1",
                    "note": "Caffeine-free option that keeps the toasty rice flavor but loses the green tea component entirely. Good for evening drinking.",
                    "ratio_multiplier": 1.0,
                },
