def _find_double_dashes(pages: list[dict]) -> list[tuple[str, str]]:
    """Walks every string value in `pages`' content and returns
    (location, offending value) pairs for anything containing a "--"
    construction. Used to guard against that pattern silently creeping
    back into new content batches, see _check_no_double_dashes below for
    why this needs to be more than a one-time cleanup."""
    hits: list[tuple[str, str]] = []

    def walk(value, location: str) -> None:
        if isinstance(value, str):
            if "--" in value:
                hits.append((location, value))
        elif isinstance(value, dict):
            for key, sub_value in value.items():
                walk(sub_value, f"{location}.{key}")
        elif isinstance(value, list):
            for i, sub_value in enumerate(value):
                walk(sub_value, f"{location}[{i}]")

    for page in pages:
        walk(page["content"], page["slug"])
    return hits


def _check_no_double_dashes() -> None:
    """The "word, dash, dash, word" construction reads as an obvious
    AI-writing tell, per direct user feedback, and every occurrence of it
    was deliberately stripped from this file's content once already.
    Because resync_content() (see below) now pushes every edit here
    straight into production on the next deploy, a new content batch that
    reintroduces this pattern would reach the live site just as reliably
    as a real fix would, so this raises immediately at import time rather
    than relying on whoever adds the next batch to remember and catch it
    themselves. Fix an offender with a comma, or a single hyphen when it's
    introducing a list right after the word describing it, never another
    double dash.
    """
    hits = _find_double_dashes(SEED_PAGES)
    if not hits:
        return
    shown = "\n".join(f"  {location}: {text!r}" for location, text in hits[:15])
    more = f"\n  ...and {len(hits) - 15} more" if len(hits) > 15 else ""
    raise ValueError(
        f"Found {len(hits)} double dash construction(s) in SEED_PAGES "
        f"content, fix each with a comma or a single hyphen:\n{shown}{more}"
    )


# template_type -> the fields every live page of that type is required to
# have populated. Each is a "component" this site's own content-depth
# standard treats as universal, not incidental -- the fields that were
# quietly missing on 11 new pages once (all skipped for pacing while a
# large content-creation batch was in flight) and had to be found by a
# manual re-audit rather than caught immediately.
#
# Two fields are deliberately absent from this list even though they look
# similar: RecipeContent.pan_size (only recipes actually baked in a shaped
# pan have one -- a cocktail or a skillet sear never will) and
# IngredientHubContent.variety_notes ("only where a real variety
# distinction exists... omit elsewhere rather than padding", per that
# field's own doc comment in types.ts). Both are conditional by design, not
# omittable-but-expected the way everything below is -- requiring them here
# would force inventing content that doesn't exist, which is exactly what
# this whole content model is built to avoid.
_REQUIRED_CONTENT_FIELDS: dict[str, list[str]] = {
    "recipe_or_dish": ["tips_and_variations", "storage_and_reheating", "reader_tips", "faqs", "step_notes", "image_alt"],
    "ingredient_hub": ["buying_tips", "pairing_suggestions", "faqs", "image_alt"],
    "howto_technique": ["intro", "common_mistakes", "equipment", "faqs", "image_alt"],
    "definition": ["faqs", "image_alt"],
    "comparison": ["faqs", "image_alt"],
    "substitute": ["faqs", "image_alt"],
    "category_roundup": ["faqs", "sub_categories"],
}


def _check_content_depth() -> None:
    """Every live page of a template type in _REQUIRED_CONTENT_FIELDS must
    have every field listed for that type populated (a non-empty list/dict/
    string) -- raises immediately at import time otherwise, the same
    enforcement pattern as _check_no_double_dashes above, and for the same
    reason: resync_content() pushes every edit here straight to production
    on the next deploy, so a new page (or batch of them) that's missing a
    component needs to be caught before it ships, not found later by a
    manual re-audit of the live site.

    A recipe's nutrition data is checked separately (nutrition_note OR at
    least one ingredient's nutrition_per_unit -- either satisfies the
    "nutrition is represented" requirement, and the two are mutually
    exclusive by design, see the seed data's own comments on
    nutrition_note).

    image_alt is required on every single-hero-image template (real,
    specific alt text, not the bare search term reused as a caption -- see
    the SEO audit that found every photo's alt text was literally just its
    Unsplash/Pexels search query, e.g. "carne asada tacos" instead of an
    actual description). category_roundup has no field of its own here
    since it has no single hero image, only per-card ones -- each
    recipe_cards entry needs its own image_alt instead, checked separately
    below rather than added to _REQUIRED_CONTENT_FIELDS, which only checks
    flat top-level content keys, not entries inside a list.
    """
    missing: list[tuple[str, str, str]] = []
    for page in SEED_PAGES:
        required = _REQUIRED_CONTENT_FIELDS.get(page["template_type"])
        if not required:
            continue
        content = page["content"]
        for field in required:
            if not content.get(field):
                missing.append((page["slug"], page["template_type"], field))
        if page["template_type"] == "recipe_or_dish":
            has_nutrition = content.get("nutrition_note") or any(
                ing.get("nutrition_per_unit") for ing in content.get("ingredients", [])
            )
            if not has_nutrition:
                missing.append((page["slug"], page["template_type"], "nutrition (note or per_unit)"))
        if page["template_type"] == "category_roundup":
            for card in content.get("recipe_cards", []):
                if not card.get("image_alt"):
                    missing.append((page["slug"], page["template_type"], f"image_alt on card {card.get('title')!r}"))
    if not missing:
        return
    shown = "\n".join(f"  [{tt}] {slug}: missing {field}" for slug, tt, field in missing[:20])
    more = f"\n  ...and {len(missing) - 20} more" if len(missing) > 20 else ""
    raise ValueError(
        f"Found {len(missing)} content-depth gap(s) in SEED_PAGES -- every "
        f"page must have every component for its template type populated:\n{shown}{more}"
    )


_TITLE_DEDUP_STOPWORDS = {"a", "an", "the", "of", "to", "for", "how", "what", "s", "vs"}


def _normalize_title_for_dedup(title: str) -> str:
    """Collapses a title to a sorted bag of its meaningful words, so two
    pages covering the same topic under superficially different titles
    ("How to Cut a Watermelon" / "How to Cut Watermelon", "Cappuccino vs.
    Latte" / "Latte vs. Cappuccino: What's the Difference?") still
    collide. Used only by _check_no_duplicate_titles below."""
    words = re.findall(r"[a-z0-9]+", title.lower())
    words = [w for w in words if w not in _TITLE_DEDUP_STOPWORDS]
    return " ".join(sorted(words))


def _check_no_duplicate_titles() -> None:
    """Two published pages of the same template_type that reduce to the
    same bag of title words are the same topic covered twice by
    independent writers -- exactly the bug a 2026-09-10 site-wide audit
    found across 11 pairs (recipes, ingredient hubs, definitions,
    comparisons, and substitutes all had at least one), most surfaced by a
    "-2" slug suffix from a naming collision at seed time that nothing
    caught before it shipped. Raises immediately at import time for the
    same reason as the checks above: resync_content() ships a new batch
    straight to production, so a collision needs to be caught before it
    goes live, not found later by another manual audit.

    Skips any page with content["unpublished"] set -- that's the
    resolution to a caught collision (keep one, unpublish the other), not
    a new one to flag, and it needs to stay silent going forward so the
    kept/unpublished pair doesn't re-trip this on every future import.
    """
    seen: dict[tuple[str, str], list[str]] = {}
    for page in SEED_PAGES:
        if page["content"].get("unpublished"):
            continue
        key = (page["template_type"], _normalize_title_for_dedup(page["title"]))
        seen.setdefault(key, []).append(page["slug"])
    dupes = {key: slugs for key, slugs in seen.items() if len(slugs) > 1}
    if not dupes:
        return
    shown = "\n".join(f"  [{tt}] {', '.join(slugs)}" for (tt, _norm), slugs in list(dupes.items())[:15])
    more = f"\n  ...and {len(dupes) - 15} more" if len(dupes) > 15 else ""
    raise ValueError(
        f"Found {len(dupes)} duplicate-title page group(s) in SEED_PAGES -- these "
        f"look like the same topic covered twice under different slugs. Keep one "
        f"and set content[\"unpublished\"] = True on the other(s):\n{shown}{more}"
    )


_check_no_double_dashes()
_check_content_depth()
_check_no_duplicate_titles()


def seed(db: Session) -> int:
    """Insert the seed pages if they don't already exist. Returns the number inserted."""
    inserted = 0
    for page in SEED_PAGES:
        exists = db.query(Page).filter(Page.slug == page["slug"]).first()
        if exists:
            continue
        db.add(
            Page(
                slug=page["slug"],
                template_type=page["template_type"],
                title=page["title"],
                status="draft",
                batch_number=page["batch_number"],
                content=page["content"],
            )
        )
        inserted += 1
    db.commit()
    return inserted



# Fields that live inside a page's content but are populated by
# fetch_stock_images.py at runtime, not defined in SEED_PAGES at all -- a
# resync must never touch these, or every already-fetched real photo would
# get silently wiped out the next time an unrelated content edit ships.
_RUNTIME_IMAGE_KEYS = ("image_url", "image_attribution")


def _merge_recipe_cards(existing_cards: list[dict], seed_cards: list[dict]) -> list[dict]:
    """recipe_cards is a list, not a flat set of keys, so it needs its own
    merge: take each card's fields from SEED_PAGES (title, description,
    image_query, ...) but keep whatever image fields that specific card
    (matched by title) already has, since those came from fetch_images(),
    not from SEED_PAGES."""
    existing_by_title = {c.get("title"): c for c in existing_cards}
    merged = []
    for seed_card in seed_cards:
        existing_card = existing_by_title.get(seed_card.get("title"), {})
        merged_card = dict(seed_card)
        for key in _RUNTIME_IMAGE_KEYS:
            if key in existing_card:
                merged_card[key] = existing_card[key]
        merged.append(merged_card)
    return merged


def resync_content(db: Session) -> int:
    """seed() never overwrites a page that already exists, which protects
    real runtime state (a fetched stock photo, most of all) but also means
    any later edit to a page's copy in SEED_PAGES, fixing a typo, sharpening
    an awkward sentence, correcting a stock-photo query, never reaches a
    page once it's already been seeded once. Only genuinely new pages
    (a new slug) pick up SEED_PAGES edits without this.

    Re-syncs every field of a page's content from SEED_PAGES except the
    runtime image fields (see _RUNTIME_IMAGE_KEYS) and recipe_cards' own
    per-card image fields (see _merge_recipe_cards), which don't exist in
    SEED_PAGES at all and would otherwise be wiped out by a naive
    overwrite. Safe to run on every startup: idempotent, a no-op once a
    page's non-image content already matches SEED_PAGES.

    Also removes a key that's no longer in SEED_PAGES at all -- e.g. a
    recipe whose nutrition_note was deliberately deleted (superseded by
    structured nutrition_per_unit data) once stayed stuck in the database
    forever, since the loop below only ever visited keys SEED_PAGES still
    had. That let a live page render two disagreeing nutrition numbers:
    the new live block from nutrition_per_unit, and the old nutrition_note
    prose nothing had ever cleared out of the stored row.
    """
    seed_by_slug = {p["slug"]: p["content"] for p in SEED_PAGES}
    updated = 0
    for page in db.query(Page).filter(Page.slug.in_(seed_by_slug.keys())).all():
        seed_content = seed_by_slug[page.slug]
        # A deep copy, not a reference -- see fetch_stock_images.py's
        # fetch_images() for why mutating page.content directly would
        # silently fail to persist.
        content = copy.deepcopy(page.content)
        changed = False
        for key in list(content.keys()):
            if key not in seed_content and key not in _RUNTIME_IMAGE_KEYS:
                del content[key]
                changed = True
        for key, seed_value in seed_content.items():
            if key in _RUNTIME_IMAGE_KEYS:
                continue
            if key == "recipe_cards":
                merged = _merge_recipe_cards(content.get(key, []), seed_value)
                if merged != content.get(key):
                    content[key] = merged
                    changed = True
            elif key == "step_notes":
                # SEED_PAGES writes this with int keys (0-based instruction
                # indexes), but a dict stored as JSON always reads back with
                # string keys -- comparing against the int-keyed seed value
                # directly would look "changed" on every single run even
                # when nothing actually differs, and rewrite the row on
                # every startup for no reason.
                normalized = {str(k): v for k, v in seed_value.items()}
                if content.get(key) != normalized:
                    content[key] = normalized
                    changed = True
            elif content.get(key) != seed_value:
                content[key] = seed_value
                changed = True
        if changed:
            page.content = content
            updated += 1
    if updated:
        db.commit()
    return updated


if __name__ == "__main__":
    session = SessionLocal()
    try:
        count = seed(session)
        print(f"Seeded {count} page(s).")
    finally:
        session.close()
